{"path": "lib/core/theme/double_bezel_card.dart", "content": "import 'package:flutter/material.dart';

class DoubleBezelCard extends StatelessWidget {
  final Widget child;
  final double outerRadius;
  final double shellPadding;

  const DoubleBezelCard({
    super.key,
    required this.child,
    this.outerRadius = 24.0,
    this.shellPadding = 6.0,
  });

  @override
  Widget build(BuildContext context) {
    final innerRadius = outerRadius - shellPadding;
    return Container(
      padding: EdgeInsets.all(shellPadding),
      decoration: BoxDecoration(
        color: const Color(0xFFF1F5F9),
        borderRadius: BorderRadius.circular(outerRadius),
        border: Border.all(color: const Color(0xFFE2E8F0)),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withOpacity(0.04),
            blurRadius: 14,
            offset: const Offset(0, 4),
          ),
        ],
      ),
      child: Container(
        padding: const EdgeInsets.all(16),
        decoration: BoxDecoration(
          color: Colors.white,
          borderRadius: BorderRadius.circular(innerRadius),
          border: Border.all(color: Colors.white),
          boxShadow: [
            BoxShadow(
              color: Colors.black.withOpacity(0.02),
              blurRadius: 6,
              offset: const Offset(0, 2),
            ),
          ],
        ),
        child: child,
      ),
    );
  }
}
"}

