{"path": "lib/features/habits/domain/habit.dart", "content": "class Habit {
  final String id;
  final String title;
  final int streak;
  final bool isCompletedToday;

  const Habit({
    required this.id,
    required this.title,
    this.streak = 0,
    this.isCompletedToday = false,
  });

  Habit copyWith({int? streak, bool? isCompletedToday}) {
    return Habit(
      id: id,
      title: title,
      streak: streak ?? this.streak,
      isCompletedToday: isCompletedToday ?? this.isCompletedToday,
    );
  }
}
"}

{"path": "test/features/habits/habit_notifier_test.dart", "content": "import 'package:flutter_test/flutter_test.dart';
import 'package:habit_app/features/habits/domain/habit.dart';
import 'package:habit_app/features/habits/presentation/habit_notifier.dart';

void main() {
  group('HabitNotifier', () {
    test('initial state is empty list', () {
      final notifier = HabitNotifier();
      expect(notifier.build(), isEmpty);
    });

    test('addHabit appends a new habit', () {
      final notifier = HabitNotifier();
      notifier.addHabit('Morning Run');
      expect(notifier.state.length, 1);
      expect(notifier.state.first.title, 'Morning Run');
    });
  });
}
"}

